<?php
session_start();require '../PRACTICAL-10/auth.php';admin_required();require '../PRACTICAL-8/db.php';$db=db();
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['toggle_id'])){$id=(int)$_POST['toggle_id'];$db->query("UPDATE users SET active=1-active WHERE id=$id");audit($db,(int)$_SESSION['user']['id'],'Changed user active status');header('Location: dashboard.php');exit;}
$stats=['users'=>0,'students'=>0,'events'=>0,'registrations'=>0];foreach(['users','students','events','registrations'] as $table){$stats[$table]=(int)$db->query("SELECT COUNT(*) FROM $table")->fetch_row()[0];}
$users=$db->query('SELECT id,name,email,role,active FROM users ORDER BY id DESC LIMIT 20')->fetch_all(MYSQLI_ASSOC);
$logs=$db->query('SELECT action,ip_address,created_at FROM audit_logs ORDER BY id DESC LIMIT 10')->fetch_all(MYSQLI_ASSOC);
?>
<!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="../PRACTICAL-7/style.css"><title>Admin Dashboard</title><style>.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.card{background:#eaf2ff;padding:18px;border-radius:10px}.card strong{font-size:28px}@media(max-width:700px){.grid{grid-template-columns:1fr 1fr}}</style></head><body><main class="box"><nav><a href="dashboard.php">Dashboard</a> | <a href="../PRACTICAL-11/students.php">Students</a> | <a href="../PRACTICAL-12/events.php">Events</a> | <a href="../PRACTICAL-10/logout.php">Logout</a></nav><h1>Admin Dashboard</h1><div class="grid"><div class="card"><span>Users</span><strong><?=$stats['users']?></strong></div><div class="card"><span>Students</span><strong><?=$stats['students']?></strong></div><div class="card"><span>Events</span><strong><?=$stats['events']?></strong></div><div class="card"><span>Registrations</span><strong><?=$stats['registrations']?></strong></div></div><h2>Users</h2><table><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Action</th></tr><?php foreach($users as $u):?><tr><td><?=htmlspecialchars($u['name'])?></td><td><?=htmlspecialchars($u['email'])?></td><td><?=htmlspecialchars($u['role'])?></td><td><?=$u['active']?'Active':'Inactive'?></td><td><form method="post"><input type="hidden" name="toggle_id" value="<?=$u['id']?>"><button><?= $u['active']?'Deactivate':'Activate'?></button></form></td></tr><?php endforeach?></table><h2>Recent Audit Log</h2><table><tr><th>Action</th><th>IP</th><th>Time</th></tr><?php foreach($logs as $l):?><tr><td><?=htmlspecialchars($l['action'])?></td><td><?=htmlspecialchars($l['ip_address'])?></td><td><?=htmlspecialchars($l['created_at'])?></td></tr><?php endforeach?></table></main></body></html>
